const settings = $('Report settings').first().json;
const { carts } = $input.first().json;
const round = (n) => Math.round(n * 100) / 100;

const orders = carts.map((cart) => ({
  id: cart.id,
  customer_id: cart.userId,
  products: cart.totalProducts,
  units: cart.totalQuantity,
  gross: round(cart.total),
  discount: round(cart.total - cart.discountedTotal),
  net: round(cart.discountedTotal),
}));

// net revenue per product across all orders
const byProduct = {};
for (const cart of carts) {
  for (const item of cart.products) {
    const row = (byProduct[item.title] ??= { title: item.title, units: 0, revenue: 0 });
    row.units += item.quantity;
    row.revenue += item.discountedTotal;
  }
}
const topProducts = Object.values(byProduct)
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 10)
  .map((p) => ({ ...p, revenue: round(p.revenue) }));

const sum = (key) => round(orders.reduce((total, order) => total + order[key], 0));
const net = sum('net');

return [{
  json: {
    report_title: settings.report_title,
    company: settings.company,
    report_month: settings.report_month,
    order_count: orders.length,
    units: sum('units'),
    gross: sum('gross'),
    discounts: sum('discount'),
    net,
    average_order: orders.length ? round(net / orders.length) : 0,
    top_products: topProducts,
    orders,
  },
}];
